import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.DNL3hc5c.js";const m=JSON.parse('{"title":"📜 Version 2.x History","description":"","frontmatter":{},"headers":[],"relativePath":"doc/8-project-and-support/releases/v2.x.md","filePath":"doc/8-project-and-support/releases/v2.x.md"}'),n={name:"doc/8-project-and-support/releases/v2.x.md"};function r(l,e,s,d,c,u){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="📜-version-2-x-history" tabindex="-1">📜 Version 2.x History <a class="header-anchor" href="#📜-version-2-x-history" aria-label="Permalink to &quot;📜 Version 2.x History&quot;">​</a></h1><h2 id="v2-11-0-2026-05-25" tabindex="-1">[v2.11.0] - 2026-05-25 <a class="header-anchor" href="#v2-11-0-2026-05-25" aria-label="Permalink to &quot;[v2.11.0] - 2026-05-25&quot;">​</a></h2><h3 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><ul><li><strong>Duration Mathematics</strong>: Introduced the <code>.balance()</code> method to <code>Tempo.Duration</code> objects to allow intelligent mathematical roll-up of duration units (e.g., converting 365 days into 1 year), with support for both strict calendar math and nominal overrides (<code>{ nominal: true }</code>).</li><li><strong>Duration Formatting</strong>: Introduced the <code>.format()</code> method to <code>Tempo.Duration</code> objects. This uses a shared, memoized internal implementation of <code>Intl.NumberFormat</code> to generate highly localized, plural-aware duration strings with excellent performance and robust cross-environment execution.</li><li><strong>Cascading Configuration</strong>: Added <code>numberFormat</code> to the <code>IntlOptions</code> interface, allowing developers to set global formatting defaults (like <code>unitDisplay: &#39;short&#39;</code>) via <code>Tempo.init()</code> that seamlessly cascade down to all <code>.format()</code> calls.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Open Core Build Fallback</strong>: Updated the <code>build:resolve</code> script to gracefully fallback to Open Core licensing types when the proprietary <code>@core</code> module is unavailable, resolving CI build failures in public GitHub Actions environments.</li></ul><h2 id="v2-10-1-2026-05-23" tabindex="-1">[v2.10.1] - 2026-05-23 <a class="header-anchor" href="#v2-10-1-2026-05-23" aria-label="Permalink to &quot;[v2.10.1] - 2026-05-23&quot;">​</a></h2><h3 id="new-features-1" tabindex="-1">New Features <a class="header-anchor" href="#new-features-1" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><ul><li>Added support for license key discovery via global browser context</li><li>Enhanced license object output with formatted timestamps</li><li>Improved terms registry with better key-based indexing</li><li>Introduced Free Showcase Astronomical Seasons premium plugin option</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Expanded license application guidance for browser, Node.js, and micro-frontend environments</li><li>Added network synchronization and offline behavior documentation</li><li>Clarified logStamp format customization examples</li><li>Improved relative time and duration string documentation</li></ul><h2 id="v2-10-0-2026-05-20" tabindex="-1">[v2.10.0] - 2026-05-20 <a class="header-anchor" href="#v2-10-0-2026-05-20" aria-label="Permalink to &quot;[v2.10.0] - 2026-05-20&quot;">​</a></h2><h3 id="new-features-2" tabindex="-1">New Features <a class="header-anchor" href="#new-features-2" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><ul><li>Added licensing system with JWT validation and revocation checks</li><li>Introduced Tempo.license public API for license state management</li><li>Enhanced Terms display with license metadata support</li><li>Term registration now enforces naming collision detection</li></ul><h3 id="bug-fixes" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fixed parsing side-effects and state leakage issues</li><li>Improved epoch timestamp precision with nanosecond-level fractional resolution for 9–10 digit timestamps</li></ul><h3 id="documentation-1" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-1" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Comprehensive licensing architecture and strategy documentation added.</li><li>Added guidance for CI-safe licensing stubs and cross-repo dependency management.</li></ul><h2 id="v2-9-3-2026-05-10" tabindex="-1">[v2.9.3] - 2026-05-10 <a class="header-anchor" href="#v2-9-3-2026-05-10" aria-label="Permalink to &quot;[v2.9.3] - 2026-05-10&quot;">​</a></h2><h3 id="🏗️-engine-stabilization-hardening" tabindex="-1">🏗️ Engine Stabilization &amp; Hardening <a class="header-anchor" href="#🏗️-engine-stabilization-hardening" aria-label="Permalink to &quot;🏗️ Engine Stabilization &amp; Hardening&quot;">​</a></h3><ul><li><strong>Timestamp Resolution Fix</strong>: Corrected configuration propagation for <code>timeStamp</code> settings, ensuring consistent persistence across nested Tempo instances.</li><li><strong>Epoch Precedence Logic</strong>: Optimized <code>parseLayout</code> to prioritize epoch-style numeric inputs, preventing layout misidentification for large timestamps.</li><li><strong>Strict Unit Enforcement</strong>: Consolidated numeric resolution to strictly respect configured <code>unit</code> preferences for both <code>Number</code> and <code>BigInt</code> types.</li><li><strong>Normalizer Leak Protection</strong>: Hardened the alias normalizer with <code>try/finally</code> blocks to ensure proper cleanup of internal resolution keys, preventing memory leaks during high-frequency parsing.</li></ul><h3 id="⚙️-type-safety-environment-engine-hardening" tabindex="-1">⚙️ Type Safety &amp; Environment Engine Hardening <a class="header-anchor" href="#⚙️-type-safety-environment-engine-hardening" aria-label="Permalink to &quot;⚙️ Type Safety &amp; Environment  Engine Hardening&quot;">​</a></h3><ul><li><strong>ZonedDateTime Mutation Ordering</strong>: Refined the internal mutation pipeline to ensure time zone and calendar application always precedes wall-clock updates.</li><li><strong>Type Interface Hardening</strong>: Resolved DOM interface collisions in internal types by correcting <code>PluginContainer</code> inheritance.</li><li><strong>Documentation Build Recovery</strong>: Patched dependency resolution between VitePress and MathJax to stabilize the documentation generation environment.</li><li><strong>Universal Type Guard Fix</strong>: Overhauled the internal <code>assertion.library</code> to eliminate &quot;never poisoning&quot; during complex union narrowing. Every type guard now explicitly specifies its target type, ensuring reliable <code>Exclude</code> and <code>Extract</code> behavior in downstream logic.</li><li><strong>Context Parity</strong>: Synchronized the functional alias &quot;Resolution Context&quot; (Host) with the public <code>Tempo</code> API. Methods like <code>this.add()</code> and <code>this.set()</code> in functional aliases now support the full range of Terms (<code>#</code>) and configuration overrides.</li></ul><h3 id="📦-dependency-updates" tabindex="-1">📦 Dependency Updates <a class="header-anchor" href="#📦-dependency-updates" aria-label="Permalink to &quot;📦 Dependency Updates&quot;">​</a></h3><ul><li><strong>Synchronized Monorepo</strong>: Updated <code>@magmacomputing/library</code> to <code>2.9.3</code>.</li><li><strong>Infrastructure Refresh</strong>: Updated core toolchain including TypeScript, Vitest, and Rollup to their latest compatible versions.</li></ul><h2 id="v2-9-2-2026-05-08" tabindex="-1">[v2.9.2] - 2026-05-08 <a class="header-anchor" href="#v2-9-2-2026-05-08" aria-label="Permalink to &quot;[v2.9.2] - 2026-05-08&quot;">​</a></h2><h3 id="new-features-3" tabindex="-1">New Features <a class="header-anchor" href="#new-features-3" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><ul><li>Enhanced Temporal support with improved timezone and calendar handling</li><li>Added documentation for prototyping with regexp patterns</li><li>Expanded installation guidance for Node.js Temporal support</li></ul><h3 id="bug-fixes-1" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-1" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Improved parsing robustness with better symbol mapping and prototype-shadowing fixes</li><li>Enhanced identity-based layout resolution</li><li>Strengthened lifecycle handling for timezone and calendar operations</li></ul><h3 id="improvements" tabindex="-1">Improvements <a class="header-anchor" href="#improvements" aria-label="Permalink to &quot;Improvements&quot;">​</a></h3><ul><li>Optimized performance with dedicated guard and normalizer modules</li><li>Updated UI styling with theme-aware color variables</li><li>Refined error handling in engine components</li></ul><h3 id="documentation-2" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-2" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Expanded main branch protection guidance</li><li>Enhanced architecture documentation with modular design overview</li></ul><h2 id="v2-9-0-2026-05-06" tabindex="-1">[v2.9.0] - 2026-05-06 <a class="header-anchor" href="#v2-9-0-2026-05-06" aria-label="Permalink to &quot;[v2.9.0] - 2026-05-06&quot;">​</a></h2><h3 id="🏗️-alias-architecture-stabilization" tabindex="-1">🏗️ Alias Architecture Stabilization <a class="header-anchor" href="#🏗️-alias-architecture-stabilization" aria-label="Permalink to &quot;🏗️ Alias Architecture Stabilization&quot;">​</a></h3><ul><li><strong>Unified Alias Engine</strong>: Completed the architectural migration to the <code>AliasEngine</code>, centralizing all registration and resolution logic for Events and Periods.</li><li><strong>Rich Metadata Results</strong>: Enhanced the resolution engine to return structured <code>AliasResult</code> objects, providing better traceability and granular control over alias-driven parses.</li><li><strong>Hardened Clock Snapping</strong>: Finalized the standardization of clock-like alias resolution, ensuring consistent sub-second precision clearing for all static and functional time aliases.</li><li><strong>Performance Optimized Monitoring</strong>: Introduced a lightweight version-tracking system to detect registry mutations, enabling <code>O(1)</code> change detection during the Tempo lifecycle.</li></ul><h3 id="⚙️-parser-registry-refinement" tabindex="-1">⚙️ Parser &amp; Registry Refinement <a class="header-anchor" href="#⚙️-parser-registry-refinement" aria-label="Permalink to &quot;⚙️ Parser &amp; Registry Refinement&quot;">​</a></h3><ul><li><strong>Consolidated Host Context</strong>: Modularized the construction of the functional alias &quot;pseudo-Tempo&quot; context, improving separation of concerns in the parsing pipeline.</li><li><strong>Legacy Decoupling</strong>: Successfully decoupled Term-based alias registration from internal raw objects, moving toward a more encapsulated and secure registry design.</li></ul><h3 id="📚-documentation-fixes" tabindex="-1">📚 Documentation Fixes <a class="header-anchor" href="#📚-documentation-fixes" aria-label="Permalink to &quot;📚 Documentation Fixes&quot;">​</a></h3><ul><li><strong>VitePress 404 Patch</strong>: Corrected root directory resolution to fix &quot;404 Not Found&quot; errors on the landing page.</li><li><strong>Build Resilience</strong>: Implemented targeted folder exclusion to prevent build-time dead-link errors in non-public directories.</li></ul><hr><h2 id="v2-8-0-2026-04-30" tabindex="-1">[v2.8.0] - 2026-04-30 <a class="header-anchor" href="#v2-8-0-2026-04-30" aria-label="Permalink to &quot;[v2.8.0] - 2026-04-30&quot;">​</a></h2><h3 id="🚨-immutability-system-refined" tabindex="-1">🚨 Immutability System Refined <a class="header-anchor" href="#🚨-immutability-system-refined" aria-label="Permalink to &quot;🚨 Immutability System Refined&quot;">​</a></h3><ul><li>The project evaluated mutation-throwing Proxies for all immutable objects, but reverted to using <code>Object.freeze</code> for stability and compatibility.</li><li>All core objects remain protected with <code>Object.freeze</code>. No mutation-throwing Proxies are used for core objects.</li><li>See plan for architectural and migration details.</li></ul><h3 id="⚙️-parse-planner-configuration" tabindex="-1">⚙️ Parse Planner Configuration <a class="header-anchor" href="#⚙️-parse-planner-configuration" aria-label="Permalink to &quot;⚙️ Parse Planner Configuration&quot;">​</a></h3><ul><li><strong>Added Parse Planner</strong>: Introduced <code>planner.layoutOrder</code> to explicitly control the parsing priority of date layouts (like <code>mdy</code> or <code>iso</code>).</li><li><strong>Pre-Filtering Optimization</strong>: Moved <code>parsePrefilter</code> to <code>planner.preFilter</code>. Legacy <code>parsePrefilter</code> configurations remain fully backward compatible.</li></ul><h3 id="🛡️-resilience-bug-fixes" tabindex="-1">🛡️ Resilience &amp; Bug Fixes <a class="header-anchor" href="#🛡️-resilience-bug-fixes" aria-label="Permalink to &quot;🛡️ Resilience &amp; Bug Fixes&quot;">​</a></h3><ul><li><strong>MonthDay Auto-Detection</strong>: Hardened the <code>monthDay</code> options resolver so that boolean shortcuts (e.g. <code>monthDay: true</code>) and manual overrides are properly tracked and never overwritten by auto-detection heuristics.</li><li><strong>Sandbox Factory Stability</strong>: Fixed bugs in the <code>Tempo.create()</code> sandbox where period alias collisions were failing silently; <code>console.warn</code> is now properly emitted when aliases overlap in local sandboxes.</li><li><strong>Symbol Discovery Isolation</strong>: Patched the <code>$setConfig</code> resolution flow to correctly merge custom formats provided via discovery symbols before evaluating global option extensions.</li></ul><hr><h2 id="v2-7-0-2026-04-27" tabindex="-1">[v2.7.0] - 2026-04-27 <a class="header-anchor" href="#v2-7-0-2026-04-27" aria-label="Permalink to &quot;[v2.7.0] - 2026-04-27&quot;">​</a></h2><h3 id="🧩-configuration-rationalization" tabindex="-1">🧩 Configuration Rationalization <a class="header-anchor" href="#🧩-configuration-rationalization" aria-label="Permalink to &quot;🧩 Configuration Rationalization&quot;">​</a></h3><ul><li><strong>Grouped Options</strong>: Consolidated regional parsing and relative time options into nested objects for improved discoverability and additive merging support. <ul><li><code>mdyLocales</code> and <code>mdyLayouts</code> → <code>monthDay: { locales, layouts }</code></li><li><code>rtfFormat</code> and <code>rtfStyle</code> → <code>relativeTime: { format, style }</code></li></ul></li><li><strong>Internal Hardening</strong>: Added <code>isMonthDay</code> internal detection to more accurately resolve parse-order layouts in regional contexts.</li></ul><h3 id="🛡️-resilience-bug-fixes-1" tabindex="-1">🛡️ Resilience &amp; Bug Fixes <a class="header-anchor" href="#🛡️-resilience-bug-fixes-1" aria-label="Permalink to &quot;🛡️ Resilience &amp; Bug Fixes&quot;">​</a></h3><ul><li><strong>Event Registry Overrides</strong>: Fixed <code>$setEvents</code> logic to ensure user-defined event aliases correctly override or merge with built-in patterns without duplication or stale matches.</li><li><strong>TimeZone Fallback Resilience</strong>: Enhanced the IANA TimeZone fallback mechanism with a cleaned-up, prioritized list of regional aliases.</li><li><strong>Intl.Locale Debugging</strong>: Improved diagnostic logging for <code>Intl.Locale</code> resolution to assist in cross-environment consistency issues.</li><li><strong>Ticker Stabilization</strong>: Further refined async generator pulse counts and termination logic.</li></ul><h3 id="⚙️-ci-cd-infrastructure" tabindex="-1">⚙️ CI/CD &amp; Infrastructure <a class="header-anchor" href="#⚙️-ci-cd-infrastructure" aria-label="Permalink to &quot;⚙️ CI/CD &amp; Infrastructure&quot;">​</a></h3><ul><li><strong>Performance Benchmarking</strong>: Integrated a dedicated <code>bench/</code> suite into the CI pipeline to monitor performance impact on core parsing and mutation logic.</li><li><strong>Workflow Optimization</strong>: Refactored the GitHub Actions workflow for better test isolation and Node.js 24 compatibility.</li></ul><h2 id="v2-6-0-2026-04-25" tabindex="-1">[v2.6.0] - 2026-04-25 <a class="header-anchor" href="#v2-6-0-2026-04-25" aria-label="Permalink to &quot;[v2.6.0] - 2026-04-25&quot;">​</a></h2><h3 id="⚠️-migration-notes" tabindex="-1">⚠️ Migration Notes <a class="header-anchor" href="#⚠️-migration-notes" aria-label="Permalink to &quot;⚠️ Migration Notes&quot;">​</a></h3><ul><li>New Features</li></ul><p>Added normalizeUtcOffset utility for transforming informal UTC-offset strings to standard format. Added layoutOrder option to customize parsing element precedence.</p><ul><li><p>Breaking Changes</p></li><li><p><strong>Season Scope Simplification</strong>: Removed the Chinese-specific object previously attached to all <code>term.season</code> scope&#39;s output. For Chinese season interpretation, create a dedicated <code>Tempo</code> instance with <code>{timeZone: &#39;Asia/Shanghai&#39;}</code> or <code>{timeZone: &#39;+08:00&#39;}</code>. Note that Chinese zodiac will still be supported on <code>term.zodiac.CN</code> as before.</p></li><li><p>Bug Fixes</p></li></ul><p>Fixed layout pattern resolution ordering to respect intended sequence. Enhanced timezone normalization for UTC offset handling.</p><ul><li>Documentation</li></ul><p>Updated architecture documentation and configuration guidance. Clarified plugin/module callback parameter ordering in examples. Added v2.6.0 migration guide for season changes.</p><h2 id="v2-5-0-2026-04-25" tabindex="-1">[v2.5.0] - 2026-04-25 <a class="header-anchor" href="#v2-5-0-2026-04-25" aria-label="Permalink to &quot;[v2.5.0] - 2026-04-25&quot;">​</a></h2><h3 id="new-features-4" tabindex="-1">New Features <a class="header-anchor" href="#new-features-4" aria-label="Permalink to &quot;New Features&quot;">​</a></h3><ul><li>Added Sandbox Factory pattern for isolated Tempo configurations via Tempo.create(options).</li><li>User-defined aliases now evaluated before built-in aliases for custom precedence.</li><li>Support for shorthand duration construction: new Tempo({ hours: 2 }).</li><li>Debug option now accepts numeric log levels for granular control.</li><li>Added fortnight event and half-hour period aliases.</li><li>Improved compact time/date parsing for 6 and 8-digit inputs.</li></ul><h3 id="documentation-3" tabindex="-1">Documentation <a class="header-anchor" href="#documentation-3" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><ul><li>Enhanced installation guidance with Temporal polyfill details.</li><li>New modularity documentation and sandbox factory pattern guide.</li><li>Added parsing cookbook with digit-only string precedence examples.</li></ul><h2 id="v2-4-0-2026-04-24" tabindex="-1">[v2.4.0] - 2026-04-24 <a class="header-anchor" href="#v2-4-0-2026-04-24" aria-label="Permalink to &quot;[v2.4.0] - 2026-04-24&quot;">​</a></h2><h3 id="🧩-parsing-infrastructure" tabindex="-1">🧩 Parsing Infrastructure <a class="header-anchor" href="#🧩-parsing-infrastructure" aria-label="Permalink to &quot;🧩 Parsing Infrastructure&quot;">​</a></h3><ul><li><strong>Layout Order Resolver</strong>: Extracted layout-ordering decision logic into a dedicated <code>engine.layout</code> module (<code>src/engine/engine.layout.ts</code>), improving internal modularity and enabling future per-input classification support. The resolver maintains 100% behavior parity with prior ordering semantics (locale-based <code>dmy</code>↔<code>mdy</code> swaps).</li><li><strong>Layout Controller Framework</strong>: Introduced a minimal but extensible controller-map structure to support future input classifications (e.g., &quot;6 digits only&quot;, &quot;contains colon&quot;). Currently ships with a single default classification that mirrors the existing layout order, ensuring zero overhead today and a clear path for Release B/C enhancements.</li></ul><h3 id="🛡️-isolation-sandboxing" tabindex="-1">🛡️ Isolation &amp; Sandboxing <a class="header-anchor" href="#🛡️-isolation-sandboxing" aria-label="Permalink to &quot;🛡️ Isolation &amp; Sandboxing&quot;">​</a></h3><ul><li><strong>Sandbox Factory Mode</strong>: Introduced <code>Tempo.create()</code>, a static factory method that generates a completely isolated <code>Tempo</code> subclass. Each sandbox maintains its own independent configuration, registry, and plugin state while inheriting from the parent, enabling multi-tenant or modular configurations within a single process without global state collisions.</li></ul><h3 id="⚙️-internal-refactoring-type-safety" tabindex="-1">⚙️ Internal Refactoring &amp; Type Safety <a class="header-anchor" href="#⚙️-internal-refactoring-type-safety" aria-label="Permalink to &quot;⚙️ Internal Refactoring &amp; Type Safety&quot;">​</a></h3><ul><li><strong>Modular Separation</strong>: Extracted the core ordering logic from <code>Tempo.#swapLayout</code>, improving code organization and unit testability without affecting public APIs.</li><li><strong>Symbol-Based Safety</strong>: Protected the default layout classification key with a <code>Symbol(&#39;default&#39;)</code>, reducing accidental tampering risk and improving internal API robustness.</li><li><strong>Determinism Coverage</strong>: Added comprehensive tests for layout order resolution, classification fallback, and multi-pair swap handling to ensure predictable behavior across locales and configurations.</li><li><strong>Module Path Flattening</strong>: Relocated core modules (e.g., <code>mutate</code>, <code>duration</code>) from <code>src/plugin/module/</code> to a top-level <code>src/module/</code> directory. This simplifies the internal architecture and provides cleaner internal import paths, reflecting their role as core library features rather than just &quot;plugins&quot;.</li></ul><h3 id="📊-diagnostics-debug-support" tabindex="-1">📊 Diagnostics &amp; Debug Support <a class="header-anchor" href="#📊-diagnostics-debug-support" aria-label="Permalink to &quot;📊 Diagnostics &amp; Debug Support&quot;">​</a></h3><ul><li><strong>Layout Order Tracing</strong>: Added optional debug emission to show the final resolved layout order when <code>debug: 5</code> is set, helping developers understand parse-order decisions.</li></ul><h2 id="v2-3-0-2026-04-22" tabindex="-1">[v2.3.0] - 2026-04-22 <a class="header-anchor" href="#v2-3-0-2026-04-22" aria-label="Permalink to &quot;[v2.3.0] - 2026-04-22&quot;">​</a></h2><h3 id="🧩-parsing-innovations" tabindex="-1">🧩 Parsing Innovations <a class="header-anchor" href="#🧩-parsing-innovations" aria-label="Permalink to &quot;🧩 Parsing Innovations&quot;">​</a></h3><ul><li><strong>Standalone Logic</strong>: Extracted the natural language engine into a dedicated <code>parse()</code> function, enabling independent datetime string resolution without requiring a full Tempo instance.</li><li><strong>Noise Filtering</strong>: Introduced a configurable <code>ignore</code> option to strip &quot;noise words&quot; during parsing, significantly increasing the robustness of the natural language interpreter.</li><li><strong>Backtracking Security</strong>: Implemented a centralized regex safety guard (<code>Match.backtrack</code>) in the snippet registry to block potentially malicious patterns and prevent catastrophic backtracking.</li></ul><h3 id="📚-documentation-ux" tabindex="-1">📚 Documentation &amp; UX <a class="header-anchor" href="#📚-documentation-ux" aria-label="Permalink to &quot;📚 Documentation &amp; UX&quot;">​</a></h3><ul><li><strong>Ecosystem Installation</strong>: Released a comprehensive installation guide covering Node.js (npm/pnpm/yarn), Deno, standard browser ESM, and specialized &quot;Lite&quot; build configurations.</li><li><strong>Interactive Demo</strong>: Enhanced the browser-based playground with a live timezone selector and real-time clock updates to demonstrate Temporal integration.</li><li><strong>Quick Start Refinement</strong>: Streamlined the README and configuration documentation to highlight simplified entry points and noise-filtering capabilities.</li></ul><h3 id="🛠️-refactor-type-safety" tabindex="-1">🛠️ Refactor &amp; Type Safety <a class="header-anchor" href="#🛠️-refactor-type-safety" aria-label="Permalink to &quot;🛠️ Refactor &amp; Type Safety&quot;">​</a></h3><ul><li><strong>State Management</strong>: Optimized the internal parser state machine to reduce memory pressure and improve resolution speed for complex strings.</li><li><strong>Type Safety</strong>: Hardened the TypeScript definitions for all <code>parse</code> and <code>term</code> resolution functions, ensuring strict type-checking without consumer-side casting.</li><li><strong>Automatic Context Sync</strong>: The engine now automatically synchronizes the hemisphere (sphere) configuration whenever the timezone is updated.</li><li><strong>Resilience</strong>: Hardened the resolution loop with safety-valves to prevent infinite loops during extreme date-range traversals and improved parse-error detection to prevent silent state corruption.</li></ul><h2 id="v2-2-6-2026-04-20" tabindex="-1">[v2.2.6] - 2026-04-20 <a class="header-anchor" href="#v2-2-6-2026-04-20" aria-label="Permalink to &quot;[v2.2.6] - 2026-04-20&quot;">​</a></h2><h3 id="🚑-emergency-hotfix" tabindex="-1">🚑 Emergency Hotfix <a class="header-anchor" href="#🚑-emergency-hotfix" aria-label="Permalink to &quot;🚑 Emergency Hotfix&quot;">​</a></h3><ul><li><strong>Isomorphic Export Architecture</strong>: Refactored <code>tempo.entry.ts</code> and Rollup configuration to ensure the browser ESM bundle exports <code>Tempo</code> as both a default and a named export. This guarantees that <code>import { Tempo } from &#39;@magmacomputing/tempo&#39;</code> functions identically across Node.js and browser environments without throwing resolution errors.</li><li><strong>Dependency Resolution</strong>: Added <code>jsbi</code> explicitly to all documentation <code>importmap</code> examples to correctly resolve <code>@js-temporal/polyfill</code> internal bare module references and eliminate <code>Failed to resolve module specifier &quot;jsbi&quot;</code> errors.</li><li><strong>Documentation &amp; UI</strong>: Fixed orphaned markdown script tags, formatted HTML browser usage blocks, and completely revamped the browser test UI pages with a premium jazzy aesthetic.</li></ul><h2 id="v2-2-5-2026-04-20" tabindex="-1">[v2.2.5] - 2026-04-20 <a class="header-anchor" href="#v2-2-5-2026-04-20" aria-label="Permalink to &quot;[v2.2.5] - 2026-04-20&quot;">​</a></h2><h3 id="🏗️-modular-hardening" tabindex="-1">🏗️ Modular Hardening <a class="header-anchor" href="#🏗️-modular-hardening" aria-label="Permalink to &quot;🏗️ Modular Hardening&quot;">​</a></h3><ul><li><strong>Singleton Resilience</strong>: Replaced <code>instanceof</code> checks in <code>TempoRuntime</code> with a cross-bundle brand check, ensuring singletons are correctly adopted across bundle boundaries and HMR reloads.</li><li><strong>Unified Discovery</strong>: Consolidated internal storage for Term and extension plugins into a single, validated <code>pluginsDb</code> structure.</li><li><strong>Resolved Shadowing</strong>: Eliminated parameter shadowing in runtime hook methods to ensure reliable event emission.</li></ul><h3 id="🔍-term-resolution-refinements" tabindex="-1">🔍 Term Resolution Refinements <a class="header-anchor" href="#🔍-term-resolution-refinements" aria-label="Permalink to &quot;🔍 Term Resolution Refinements&quot;">​</a></h3><ul><li><strong>Chronological Stability</strong>: Enforced chronological sorting in <code>resolveCycleWindow</code> for accurate cycle anchor identification.</li><li><strong>Absolute vs Relative Years</strong>: Normalized year handling to allow templates to mix relative offsets and absolute historical years seamlessly.</li></ul><h3 id="📚-documentation-ux-1" tabindex="-1">📚 Documentation &amp; UX <a class="header-anchor" href="#📚-documentation-ux-1" aria-label="Permalink to &quot;📚 Documentation &amp; UX&quot;">​</a></h3><ul><li><strong>Standards Mode</strong>: Modernized all public demonstration files with proper HTML5 skeletons and metadata.</li><li><strong>Contextual Guidance</strong>: Updated architecture docs and READMEs with accurate module paths and functional importmap examples.</li></ul><h2 id="v2-2-4-2026-04-19" tabindex="-1">[v2.2.4] - 2026-04-19 <a class="header-anchor" href="#v2-2-4-2026-04-19" aria-label="Permalink to &quot;[v2.2.4] - 2026-04-19&quot;">​</a></h2><h3 id="🛡️-production-safety" tabindex="-1">🛡️ Production Safety <a class="header-anchor" href="#🛡️-production-safety" aria-label="Permalink to &quot;🛡️ Production Safety&quot;">​</a></h3><ul><li><strong>Immutable Compatibility</strong>: Added redefinition guards to <code>TickerModule</code> to prevent errors on already-frozen classes.</li><li><strong>ESM Integrity</strong>: Bundled <code>tslib</code> into granular ESM builds to resolve resolution failures in standard browser environments.</li></ul><h2 id="v2-2-3-2026-04-19" tabindex="-1">[v2.2.3] - 2026-04-19 <a class="header-anchor" href="#v2-2-3-2026-04-19" aria-label="Permalink to &quot;[v2.2.3] - 2026-04-19&quot;">​</a></h2><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to &quot;✨ New Features&quot;">​</a></h3><ul><li><strong>Modular Parsing</strong>: Initial decoupling of the parse engine to support standalone usage.</li><li><strong>Layout Snippets</strong>: Introduced pattern-based layout customization for granular formatting control.</li><li><strong>Project Governance</strong>: Integrated the MIT license and established a dedicated release history.</li></ul><h3 id="🐛-bug-fixes" tabindex="-1">🐛 Bug Fixes <a class="header-anchor" href="#🐛-bug-fixes" aria-label="Permalink to &quot;🐛 Bug Fixes&quot;">​</a></h3><ul><li><strong>Match Propagation</strong>: Ensured parse results correctly propagate through instance clones.</li><li><strong>Drift Resolution</strong>: Corrected timezone and calendar drift during intensive mutation cycles.</li></ul><h3 id="📚-documentation-chores" tabindex="-1">📚 Documentation &amp; Chores <a class="header-anchor" href="#📚-documentation-chores" aria-label="Permalink to &quot;📚 Documentation &amp; Chores&quot;">​</a></h3><ul><li><strong>Knowledge Architecture</strong>: Reorganized navigation into focused tracks: Cookbook, Advanced Reference, and Utility Library.</li><li><strong>API Reference</strong>: Expanded constructor documentation and added guidance for custom enum implementations.</li><li><strong>Diagnostics</strong>: Improved internal module-loading error messages for easier troubleshooting.</li></ul><h2 id="v2-2-2-2026-04-18" tabindex="-1">[v2.2.2] - 2026-04-18 <a class="header-anchor" href="#v2-2-2-2026-04-18" aria-label="Permalink to &quot;[v2.2.2] - 2026-04-18&quot;">​</a></h2><h3 id="🛡️-registry-stabilization" tabindex="-1">🛡️ Registry Stabilization <a class="header-anchor" href="#🛡️-registry-stabilization" aria-label="Permalink to &quot;🛡️ Registry Stabilization&quot;">​</a></h3><ul><li>Globalized module and serialization registries using <code>Symbol.for()</code> on <code>globalThis</code> to ensure state consistency across module reloads, HMR, and bundled distributions.</li><li>Implemented secure, local Proxy wrapping for registries to prevent closure persistence across library reloads.</li></ul><h3 id="🔍-hardened-reflection" tabindex="-1">🔍 Hardened Reflection <a class="header-anchor" href="#🔍-hardened-reflection" aria-label="Permalink to &quot;🔍 Hardened Reflection&quot;">​</a></h3><ul><li>Fixed static property reflection for decorated classes by implementing recursive prototype chain traversal in <code>getAccessors</code>.</li><li>Refined prototype walking logic to prevent leaks from <code>Object.prototype</code> and <code>Function.prototype</code>.</li></ul><h3 id="📦-production-optimization" tabindex="-1">📦 Production Optimization <a class="header-anchor" href="#📦-production-optimization" aria-label="Permalink to &quot;📦 Production Optimization&quot;">​</a></h3><ul><li>Achieved 100% build parity and test coverage in the production distribution (<code>test:dist</code>).</li><li>Reduced NPM package size by nearly 50% by excluding non-essential documentation and image assets from the public package.</li><li>Hardened Rollup build paths to be context-aware and defensive against missing artifacts.</li></ul><h3 id="🎨-premium-documentation-ux" tabindex="-1">🎨 Premium Documentation &amp; UX <a class="header-anchor" href="#🎨-premium-documentation-ux" aria-label="Permalink to &quot;🎨 Premium Documentation &amp; UX&quot;">​</a></h3><ul><li>Redesigned the documentation landing page with a custom, high-performance Hero section and a live Tempo-driven analog clock.</li><li>Harmonized branding across README and documentation sites with &quot;Tempo Blue&quot; styling.</li><li>Fixed routing and asset resolution for GitHub Pages deployments using VitePress base-path helpers.</li></ul><h3 id="🧬-mutation-engine-state-preservation" tabindex="-1">🧬 Mutation Engine &amp; State Preservation <a class="header-anchor" href="#🧬-mutation-engine-state-preservation" aria-label="Permalink to &quot;🧬 Mutation Engine &amp; State Preservation&quot;">​</a></h3><ul><li>Stabilized the mutation engine (<code>.add()</code>, <code>.set()</code>) to correctly accumulate and preserve parse results across instance clones.</li><li>Implemented robust parse result propagation in <code>MutateModule</code> using the internal <code>state.matches</code> registry.</li><li>Standardized cross-module state access using the <code>[sym.$Internal]</code> symbol, enabling safe cloning without violating private encapsulation.</li><li>Resolved timezone and calendar drift during complex mutations by enforcing authoritative state-merging in the mutation pipeline.</li></ul><h3 id="🧩-modular-parse-engine" tabindex="-1">🧩 Modular Parse Engine <a class="header-anchor" href="#🧩-modular-parse-engine" aria-label="Permalink to &quot;🧩 Modular Parse Engine&quot;">​</a></h3><ul><li>Successfully decoupled internal parsing logic into <code>ParseModule</code>, reducing core class complexity.</li><li>Implemented a hybrid static <code>Tempo.parse</code> configuration/method pattern to maintain full backward compatibility while supporting modular delegation.</li><li>Hardened the <code>interpret</code> utility to ensure reliable method dispatching even when modules are loaded lazily or via HMR.</li></ul><h3 id="⚙️-ci-cd-tooling" tabindex="-1">⚙️ CI/CD &amp; Tooling <a class="header-anchor" href="#⚙️-ci-cd-tooling" aria-label="Permalink to &quot;⚙️ CI/CD &amp; Tooling&quot;">​</a></h3><ul><li>Upgraded GitHub Actions pipeline to <strong>Node.js 24</strong> to resolve deprecation warnings.</li><li>Restored separate &quot;Full&quot; and &quot;Core&quot; test suite isolation in local and workspace Vitest configurations.</li><li>Standardized documentation build order to ensure artifacts are compiled before generation.</li><li>Achieved <strong>100% Test Pass Rate</strong> (384/384) across all environments and distribution bundles.</li></ul><h2 id="v2-1-3-2026-04-18" tabindex="-1">[v2.1.3] - 2026-04-18 <a class="header-anchor" href="#v2-1-3-2026-04-18" aria-label="Permalink to &quot;[v2.1.3] - 2026-04-18&quot;">​</a></h2><h3 id="📚-documentation-ecosystem" tabindex="-1">📚 Documentation &amp; Ecosystem <a class="header-anchor" href="#📚-documentation-ecosystem" aria-label="Permalink to &quot;📚 Documentation &amp; Ecosystem&quot;">​</a></h3><ul><li><strong>VitePress Migration</strong>: Launched a modern documentation system with integrated TypeDoc API references.</li><li><strong>Loading Patterns</strong>: Introduced interactive browser demos for ESM, IIFE, and granular module resolution.</li><li><strong>Standardized README</strong>: Refreshed the main project entry point with improved formatting and developer guides.</li></ul><h3 id="🚀-performance-extensibility" tabindex="-1">🚀 Performance &amp; Extensibility <a class="header-anchor" href="#🚀-performance-extensibility" aria-label="Permalink to &quot;🚀 Performance &amp; Extensibility&quot;">​</a></h3><ul><li><strong>Plugin Refactor</strong>: Migrated the plugin system to a flexible object-based API for better extensibility.</li><li><strong>Cache Optimization</strong>: Enhanced memoization performance across the core engine.</li><li><strong>Modular Exports</strong>: Streamlined library entry points to improve tree-shaking and reduce bundle sizes.</li></ul><h3 id="⏱️-temporal-utilities" tabindex="-1">⏱️ Temporal Utilities <a class="header-anchor" href="#⏱️-temporal-utilities" aria-label="Permalink to &quot;⏱️ Temporal Utilities&quot;">​</a></h3><ul><li><strong>High Precision</strong>: Expanded Temporal utility functions with native support for nanosecond-precision calculations.</li></ul><h2 id="v2-1-2-2026-04-16" tabindex="-1">[v2.1.2] - 2026-04-16 <a class="header-anchor" href="#v2-1-2-2026-04-16" aria-label="Permalink to &quot;[v2.1.2] - 2026-04-16&quot;">​</a></h2><p>Tempo v2.1.2 is a major milestone, delivering a more reactive architecture and rock-solid stability.</p><h3 id="🏗️-modular-architecture" tabindex="-1">🏗️ Modular Architecture <a class="header-anchor" href="#🏗️-modular-architecture" aria-label="Permalink to &quot;🏗️ Modular Architecture&quot;">​</a></h3><p>Tempo is now split into <code>core</code> and optional modules, allowing you to include only what you need. This reduces bundle size for users who only need the basic engine.</p><h3 id="📝-improved-logging" tabindex="-1">📝 Improved Logging <a class="header-anchor" href="#📝-improved-logging" aria-label="Permalink to &quot;📝 Improved Logging&quot;">​</a></h3><p>Internal logging now uses context-aware Symbols. This decouples the logging logic from the core engine, allowing for cleaner diagnostics without performance overhead.</p><h3 id="⏱️-static-api" tabindex="-1">⏱️ Static API <a class="header-anchor" href="#⏱️-static-api" aria-label="Permalink to &quot;⏱️ Static API&quot;">​</a></h3><ul><li>Added <code>Tempo.duration()</code> static method for convenient duration creation without instantiating a full Tempo date object first.</li></ul><h3 id="🔌-side-effect-registration" tabindex="-1">🔌 Side Effect Registration <a class="header-anchor" href="#🔌-side-effect-registration" aria-label="Permalink to &quot;🔌 Side Effect Registration&quot;">​</a></h3><p>Plugins now support automatic registration.</p><ul><li>The full <code>@magmacomputing/tempo</code> package includes all modules by default.</li><li>Core users (<code>@magmacomputing/tempo/core</code>) can activate features simply by importing the corresponding module (e.g., <code>import &#39;@magmacomputing/tempo/ticker&#39;</code>).</li></ul><h3 id="🛡️-100-reliability" tabindex="-1">🛡️ 100% Reliability <a class="header-anchor" href="#🛡️-100-reliability" aria-label="Permalink to &quot;🛡️ 100% Reliability&quot;">​</a></h3><p>The engine passes all regression tests, ensuring complete stability across:</p><ul><li>Parsing complex date strings.</li><li>Calculation and relative math.</li><li>Formatting routines.</li></ul><h3 id="🗓️-unified-term-logic" tabindex="-1">🗓️ Unified Term Logic <a class="header-anchor" href="#🗓️-unified-term-logic" aria-label="Permalink to &quot;🗓️ Unified Term Logic&quot;">​</a></h3><p>Terms (like Quarters and Seasons) are now fully integrated:</p><ul><li>Use <code>#</code> in <code>set()</code> to jump to boundaries (e.g., <code>t.set({ start: &#39;#quarter&#39; })</code>).</li><li>Use <code>{#term}</code> in <code>format()</code> to embed semantic labels (e.g. &quot;Second Quarter&quot;) directly into strings (e.g., <code>t.format(&#39;Today is {yyyy}-{mm}-{dd} in the {#quarter}&#39;)</code>.</li></ul><h3 id="➗-relational-term-math" tabindex="-1">➗ Relational Term Math <a class="header-anchor" href="#➗-relational-term-math" aria-label="Permalink to &quot;➗ Relational Term Math&quot;">​</a></h3><p>A category-first feature. Shift dates by semantic &quot;steps&quot; with <code>.add({ &#39;#quarter&#39;: 1 })</code>. Tempo preserves your relative duration within the Term, jumping across gaps and handling overflows with mathematical precision.</p><h3 id="🔗-fluent-immutable-boundaries" tabindex="-1">🔗 Fluent Immutable Boundaries <a class="header-anchor" href="#🔗-fluent-immutable-boundaries" aria-label="Permalink to &quot;🔗 Fluent Immutable Boundaries&quot;">​</a></h3><p>Term ranges now return fully functional, frozen <code>Tempo</code> instances for <code>start</code> and <code>end</code>. This allows for seamless chaining:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t.term.qtr.start.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{dd} {mmm}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="⚡-ticker-reliability" tabindex="-1">⚡ Ticker Reliability <a class="header-anchor" href="#⚡-ticker-reliability" aria-label="Permalink to &quot;⚡ Ticker Reliability&quot;">​</a></h3><p>Fully stabilized the Ticker subsystem:</p><ul><li>Resolved async generator hangs.</li><li>Synchronized pulse counts (<code>N</code> pulses for <code>limit: N</code>), guaranteeing 100% predictable reactive streams.</li></ul><h3 id="🚀-parsing-engine-optimization" tabindex="-1">🚀 Parsing Engine Optimization <a class="header-anchor" href="#🚀-parsing-engine-optimization" aria-label="Permalink to &quot;🚀 Parsing Engine Optimization&quot;">​</a></h3><ul><li>Re-engineered pattern generation for <code>O(1)</code> instance creation.</li><li>Improved support for custom layout literals in local/one-off parsers.</li><li>Significant refinements to the natural language engine for even more intuitive relative-date handling (&quot;next Friday&quot;, &quot;two days ago&quot;, etc.).</li></ul>',155)])])}const g=i(n,[["render",r]]);export{m as __pageData,g as default};
